/// <summary>
/// Resolves <see cref="EmbeddedResourceResource"/> by which required keys are present, since
/// nothing in the payload names the variant.
/// </summary>
internal sealed class EmbeddedResourceResourceConverter : JsonConverter<EmbeddedResourceResource>
{
    /// <inheritdoc/>
    public override EmbeddedResourceResource Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        if (root.TryGetProperty("text", out _) && root.TryGetProperty("uri", out _))
        {
            return new EmbeddedResourceResourceTextResourceContents
            {
                Value = AcpJson.Read<TextResourceContents>(root, options)
            };
        }

        if (root.TryGetProperty("blob", out _) && root.TryGetProperty("uri", out _))
        {
            return new EmbeddedResourceResourceBlobResourceContents
            {
                Value = AcpJson.Read<BlobResourceContents>(root, options)
            };
        }

        return new EmbeddedResourceResourceUnknown
        {
            Raw = root.Clone()
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, EmbeddedResourceResource value, JsonSerializerOptions options)
    {
        switch (value)
        {
            case EmbeddedResourceResourceTextResourceContents typed:
            JsonSerializer.Serialize(writer, typed.Value, options.GetTypeInfo(typeof(TextResourceContents)));
            break;
            case EmbeddedResourceResourceBlobResourceContents typed:
            JsonSerializer.Serialize(writer, typed.Value, options.GetTypeInfo(typeof(BlobResourceContents)));
            break;
            case EmbeddedResourceResourceUnknown unknown:
            unknown.Raw.WriteTo(writer);
            break;
            default:
            writer.WriteNullValue();
            break;
        }
    }
}

