/// <summary>
/// Configuration for connecting to an MCP (Model Context Protocol) server.
///
/// MCP servers provide tools and context that the agent can use when
/// processing prompts.
///
/// See protocol docs: [MCP Servers](https://agentclientprotocol.com/protocol/v2/session-setup#mcp-servers)
/// </summary>
[JsonConverter(typeof(McpServerConverter))]
public abstract class McpServer
{
    /// <summary>The value of <c>type</c> that selects this variant.</summary>
    [JsonIgnore]
    public abstract string Discriminator { get; }
}

/// <summary>
/// A <see cref="McpServer"/> variant this protocol version does not define.
/// </summary>
/// <remarks>
/// Holds the payload verbatim so it can be stored, replayed, or proxied unchanged.
/// ACP v2 requires that; failing to parse instead would lose the whole message.
/// </remarks>
public sealed class McpServerUnknown : McpServer
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override string Discriminator => Kind;
    /// <summary>The discriminator value that was received.</summary>
    public required string Kind { get; init; }
    /// <summary>The payload exactly as it arrived.</summary>
    public required JsonElement Raw { get; init; }
}

/// <summary>Resolves <see cref="McpServer"/> by its <c>type</c> discriminator.</summary>
internal sealed class McpServerConverter : JsonConverter<McpServer>
{
    /// <inheritdoc/>
    public override McpServer Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("type", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "http" => AcpJson.Read<McpServerHttp>(root, options),
            "stdio" => AcpJson.Read<McpServerStdio>(root, options),
            _ => new McpServerUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, McpServer value, JsonSerializerOptions options)
    {
        if (value is McpServerUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("type", value.Discriminator);
        switch (value)
        {
            case McpServerHttp typed:
            AcpJson.WriteMembers(writer, typed, options);
            break;
            case McpServerStdio typed:
            AcpJson.WriteMembers(writer, typed, options);
            break;
            default:
            break;
        }

        writer.WriteEndObject();
    }
}

