/// <summary>Resolves <see cref="ToolCallContent"/> by its <c>type</c> discriminator.</summary>
internal sealed class ToolCallContentConverter : JsonConverter<ToolCallContent>
{
    /// <inheritdoc/>
    public override ToolCallContent Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
    {
        using var document = JsonDocument.ParseValue(ref reader);
        var root = document.RootElement;
        var kind = root.TryGetProperty("type", out var marker) && marker.ValueKind == JsonValueKind.String ? marker.GetString() : null;
        return kind switch
        {
            "content" => new ToolCallContentContent
            {
                Value = AcpJson.Read<Content>(root, options)
            },
            "diff" => new ToolCallContentDiff
            {
                Value = AcpJson.Read<Diff>(root, options)
            },
            "terminal" => new ToolCallContentTerminal
            {
                Value = AcpJson.Read<Terminal>(root, options)
            },
            _ => new ToolCallContentUnknown
            {
                Kind = kind ?? string.Empty,
                Raw = root.Clone()
            },
        };
    }

    /// <inheritdoc/>
    public override void Write(Utf8JsonWriter writer, ToolCallContent value, JsonSerializerOptions options)
    {
        if (value is ToolCallContentUnknown unknown)
        {
            unknown.Raw.WriteTo(writer);
            return;
        }

        writer.WriteStartObject();
        writer.WriteString("type", value.Discriminator);
        switch (value)
        {
            case ToolCallContentContent typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ToolCallContentDiff typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            case ToolCallContentTerminal typed:
            AcpJson.WriteMembers(writer, typed.Value, options);
            break;
            default:
            break;
        }

        writer.WriteEndObject();
    }
}

